          { key: 'cardio', label: 'Cardiovascular', type: 'seg', default: '0', options: [ { value: '0', label: 'Pink' }, { value: '1', label: 'Pale' }, { value: '2', label: 'Grey/mottled' }, { value: '3', label: 'Grey + clammy' } ] },
          { key: 'resp', label: 'Respiratory', type: 'seg', default: '0', options: [ { value: '0', label: 'Normal' }, { value: '1', label: 'Mild distress' }, { value: '2', label: 'Moderate' }, { value: '3', label: 'Severe' } ] }
