            interpretation: high || total >= 5 ? 'High risk — urgent senior/rapid-response review indicated.' : total >= 3 ? 'Increased risk — increase monitoring frequency, consider senior review.' : 'Low risk — routine monitoring.',
            action: high || total >= 5 ? 'Escalate immediately for senior clinician / rapid response assessment.' : total >= 3 ? 'Recheck vitals more frequently and notify senior team member.' : 'Continue routine observation schedule.',
            caution: 'Any single parameter scored 3 warrants urgent review regardless of total score. This score is an adjunct to, not a replacement for, clinical judgment.',
            reference: 'Adapted from Brighton/bedside PEWS models; institutional scoring may differ.'
