          { key: 'nights', label: 'Nighttime awakenings', type: 'seg', default: '0', options: [ { value: '0', label: 'None' }, { value: '1', label: '1–2×/mo' }, { value: '2', label: '3–4×/mo' }, { value: '3', label: '>1×/wk' } ] },
          { key: 'activity', label: 'Activity limitation', type: 'seg', default: '0', options: [ { value: '0', label: 'None' }, { value: '1', label: 'Minor' }, { value: '2', label: 'Some' }, { value: '3', label: 'Extreme' } ] },
          { key: 'saba', label: 'SABA use', type: 'seg', default: '0', options: [ { value: '0', label: '≤2 days/wk' }, { value: '1', label: '>2 days/wk' }, { value: '2', label: 'Daily' }, { value: '3', label: 'Multiple/day' } ] }
